import { useContext, useMemo } from '@wordpress/element';
import { useSelect } from '@wordpress/data';
import { getBlockType, store as blocksStore } from '@wordpress/blocks';
import { privateApis as globalStylesEnginePrivateApis } from '@wordpress/global-styles-engine';
import type { GlobalStylesConfig } from '@wordpress/global-styles-engine';
import { store as blockEditorStore } from '../../store';
import {
	globalStylesDataKey,
	globalStylesLinksDataKey,
} from '../../store/private-keys';
import { getVariationNameFromClass } from '../../hooks/block-style-variation';
import { useBlockEditContext } from '../block-edit/context';
import BlockContext from '../block-context';
import { unlock } from '../../lock-unlock';
import type { BlockStyleState } from '../../hooks/types';

const { resolveStyle } = unlock( globalStylesEnginePrivateApis );

/**
 * Reads the Global Styles payload and returns it as a `GlobalStylesConfig`
 * (`{ styles, _links }`), the shape `resolveStyle` expects. `_links` carries
 * the theme-file map used to resolve pointers such as background images.
 *
 * @return Global Styles config, or `null` before the payload settles.
 */
function useRawGlobalStyles(): GlobalStylesConfig | null {
	const { rawGlobalStylesData, links } = useSelect( ( select ) => {
		const settings = select( blockEditorStore ).getSettings();
		return {
			rawGlobalStylesData: settings[ globalStylesDataKey ] ?? null,
			links: settings[ globalStylesLinksDataKey ] ?? null,
		};
	}, [] );
	return useMemo(
		() =>
			rawGlobalStylesData
				? // The settings hold the global styles data and their links.
					( {
						styles: rawGlobalStylesData,
						_links: links ?? undefined,
					} as GlobalStylesConfig )
				: null,
		[ rawGlobalStylesData, links ]
	);
}

/**
 * Blocks whose heading level is handed down by a parent through block context
 * rather than held in their own `level` attribute, mapped to that context key
 * and the level they fall back to.
 *
 * Accordion Heading is the only one: the parent Accordion owns the level, and
 * the child's `level` attribute has no default and is absent on pattern-,
 * template- and paste-inserted blocks.
 */
const CONTEXT_HEADING_LEVEL_BLOCKS: Record<
	string,
	{ contextKey: string; fallbackLevel: number } | undefined
> = {
	'core/accordion-heading': {
		contextKey: 'core/accordion-heading-level',
		fallbackLevel: 3,
	},
};

/**
 * Resolves the heading level that selects a block's `h1`-`h6` element layer.
 *
 * @param blockName      Block name.
 * @param levelAttribute The block's own `level` attribute, if it has one.
 * @param contextLevel   Level supplied by a parent through block context.
 * @return Resolved heading level, or `undefined` when the block has none.
 */
function getHeadingLevel(
	blockName: string,
	levelAttribute: number | undefined,
	contextLevel: number | undefined
): number | undefined {
	const contextOwned = CONTEXT_HEADING_LEVEL_BLOCKS[ blockName ];
	if ( ! contextOwned ) {
		return levelAttribute;
	}
	// Mirrors the block's own chain (Accordion Heading saves `h${ level || 3 }`),
	// so `0` coerces to the fallback instead of reading as a level-0 state.
	return levelAttribute || contextLevel || contextOwned.fallbackLevel;
}

/**
 * Reads the heading level a parent supplies through block context.
 *
 * Only the blocks in `CONTEXT_HEADING_LEVEL_BLOCKS` read a key: the value
 * reaches every descendant, so an ordinary Heading inside an Accordion Panel
 * must not pick it up. Returns a primitive so callers can use it as a
 * `useSelect` dependency.
 *
 * @param blockName Block name.
 * @return Level from block context, or `undefined`.
 */
function useContextHeadingLevel(
	blockName: string | null | undefined
): number | undefined {
	const blockContext = useContext( BlockContext );
	// A missing block name matches no block.
	const contextKey =
		CONTEXT_HEADING_LEVEL_BLOCKS[ blockName as string ]?.contextKey;
	// The parent block supplies the level as a number.
	return contextKey ? ( blockContext[ contextKey ] as number ) : undefined;
}

/**
 * The block types that render as a root-level Global Styles *element*, keyed
 * by element: their whole selves are painted by `styles.elements[ key ]` on
 * the canvas, in addition to (or instead of) the block's own class. A Button
 * renders `.wp-element-button`, a level-2 Heading renders `<h2>`.
 *
 * Hand-maintained by necessity: the block-to-element relationship is not
 * inferable from block metadata. `supports.color.link` and friends mark blocks
 * that *contain* an element, not blocks that *are* one, and only the inverse
 * element-to-selector map exists (`__EXPERIMENTAL_ELEMENTS`). Standardizing it
 * as a block property is tracked in
 * https://github.com/WordPress/gutenberg/issues/80438.
 *
 * Only blocks whose visible text is the link are listed under `link`. Read
 * More and the next and previous pagination links render `<a>` as their whole
 * selves. The blocks in `LINK_WRAPPER_BLOCK_TYPES` wrap a single link in a
 * `<div>`, so the element paints their text but their own styles land on the
 * wrapper. Blocks that merely *contain* a link (the heading family, Paragraph,
 * Group, and the hybrid blocks with a Link colour control such as Post Author
 * Name and Post Date) are left out: their inner-link control reads the
 * `inheritedValue.elements.link` passthrough instead, so folding `link` in
 * would bleed link color into the block's own text.
 */
const ELEMENT_BLOCK_TYPES: Record< string, string[] > = {
	button: [ 'core/button' ],
	// Each also takes the `h1`-`h6` layer for its level, see `getElementLayers`.
	heading: [
		'core/accordion-heading',
		'core/heading',
		'core/post-title',
		'core/site-title',
		'core/query-title',
		'core/comments-title',
		'core/term-name',
		'core/site-tagline',
	],
	// Whole-block link blocks: the entire block renders as an `<a>`, so the
	// root `styles.elements.link` layer paints it, mirroring how `button`
	// paints Button. For the blocks whose `color.text` support is disabled
	// this is inert at the (hidden) text control while their typography
	// controls now reflect the link element; Read More (`color.text: true`)
	// surfaces the inherited link color at its Text control.
	link: [
		'core/read-more',
		'core/query-pagination-next',
		'core/query-pagination-previous',
		'core/comments-pagination-next',
		'core/comments-pagination-previous',
	],
};

// Painted by the `link` element, but their block styles reach only the wrapper,
// so the element still wins on the inner `<a>`.
const LINK_WRAPPER_BLOCK_TYPES = [
	'core/loginout',
	'core/post-navigation-link',
	'core/query-pagination-numbers',
	'core/comments-pagination-numbers',
	'core/comment-edit-link',
	'core/comment-reply-link',
	'core/post-comments-link',
];

const HEADING_LEVEL_ELEMENTS = new Set( [
	'h1',
	'h2',
	'h3',
	'h4',
	'h5',
	'h6',
] );

/**
 * Maps a block to the root-level Global Styles element layers that paint it
 * on the canvas. See `ELEMENT_BLOCK_TYPES`.
 *
 * Keys are ordered low to high precedence, so a level-specific `h2` wins over
 * the generic `heading`. A level of `0` (e.g. a Site or Post Title rendered as
 * a paragraph) renders no heading tag, so no element layer applies.
 *
 * @param blockName    Block name.
 * @param headingLevel Resolved heading level, from `getHeadingLevel`.
 * @return Ordered element keys, low to high precedence.
 */
function getElementLayers(
	blockName: string,
	headingLevel: number | undefined
): string[] {
	if ( LINK_WRAPPER_BLOCK_TYPES.includes( blockName ) ) {
		return [ 'link' ];
	}
	const element = Object.keys( ELEMENT_BLOCK_TYPES ).find( ( key ) =>
		ELEMENT_BLOCK_TYPES[ key ].includes( blockName )
	);
	if ( ! element ) {
		return [];
	}
	if ( element !== 'heading' ) {
		return [ element ];
	}
	if ( headingLevel === 0 ) {
		return [];
	}
	return headingLevel ? [ 'heading', `h${ headingLevel }` ] : [ 'heading' ];
}

/**
 * The inverse of `getElementLayers`: the block types a root-level Global
 * Styles element paints as their whole selves. `h1`-`h6` give the heading
 * family, since its blocks can render at any level. Blocks that wrap their
 * link, and heading blocks that default to level `0` (a paragraph), are left
 * out.
 *
 * @param element Element key, e.g. `heading`, `h2` or `button`.
 * @return Block names, or an empty array for an element no block renders as.
 */
export function getBlockTypesForElement( element: string ): string[] {
	const key = HEADING_LEVEL_ELEMENTS.has( element ) ? 'heading' : element;
	if ( ! Object.hasOwn( ELEMENT_BLOCK_TYPES, key ) ) {
		return [];
	}
	if ( key !== 'heading' ) {
		return ELEMENT_BLOCK_TYPES[ key ];
	}
	return ELEMENT_BLOCK_TYPES.heading.filter(
		( blockName ) =>
			getBlockType( blockName )?.attributes?.level?.default !== 0
	);
}

/**
 * Element layers for a block, from its attributes and block context. The
 * non-hook form of what `useResolvedStyle` derives.
 *
 * @param blockName    Block name.
 * @param attributes   Block attributes.
 * @param blockContext Block context passed to the block's edit.
 * @return Ordered element keys, low to high precedence.
 */
export function getBlockElementLayers(
	blockName: string,
	attributes: { level?: number } | null | undefined,
	blockContext?: Record< string, unknown > | null
): string[] {
	const contextKey = CONTEXT_HEADING_LEVEL_BLOCKS[ blockName ]?.contextKey;
	return getElementLayers(
		blockName,
		getHeadingLevel(
			blockName,
			attributes?.level,
			contextKey
				? ( blockContext?.[ contextKey ] as number | undefined )
				: undefined
		)
	);
}

/**
 * Internal hook that derives the active block-style-variation slug from a
 * block's `className` by matching registered styles via
 * `getVariationNameFromClass`, together with the element layers that paint
 * the block. Both come from a single store subscription.
 *
 * The lookup is scoped to a single `useSelect` subscription; the
 * `@wordpress/blocks` registered-styles slice changes only when a block's
 * styles are (un)registered, so this subscription is cold in steady-state
 * editor use.
 *
 * The block's `clientId` comes from the block edit context rather than an
 * argument: these panels always render inside `BlockEditContextProvider`, so
 * the caller does not have to thread it through.
 *
 * @param blockName Block name (e.g. `core/heading`).
 * @param className Space-separated class string from block attributes.
 * @return Variation slug
 * (without the `is-style-` prefix) and the block's heading level, if any.
 */
function useVariationAndElements(
	blockName: string | null | undefined,
	className: string | null | undefined
): {
	variationName: string | null | undefined;
	headingLevel: number | undefined;
} {
	const { clientId } = useBlockEditContext();
	const contextHeadingLevel = useContextHeadingLevel( blockName );
	return useSelect(
		( select ) => {
			if ( ! blockName ) {
				return { variationName: null, headingLevel: undefined };
			}
			const registeredStyles =
				select( blocksStore ).getBlockStyles( blockName );
			const { level } = ( select( blockEditorStore ).getBlockAttributes(
				// Global styles panels render inside the edited block.
				clientId!
			) || {} ) as { level?: number };
			// Primitives only: `useSelect` shallow-compares this object, so
			// returning a fresh array here would re-render on every action.
			return {
				variationName: className
					? getVariationNameFromClass( className, registeredStyles )
					: null,
				headingLevel: getHeadingLevel(
					blockName,
					level,
					contextHeadingLevel
				),
			};
		},
		[ blockName, className, clientId, contextHeadingLevel ]
	);
}

/**
 * Hook: computes the merged, cascade-resolved `inheritedValue` payload and
 * source map for a selected block, ready to hand to a shared Global Styles
 * panel via props.
 *
 * It reads the merged Global Styles payload and the block's applied variation,
 * then folds the Root ‹ Block-type ‹ applied-variation cascade (resolving
 * `{ ref }` envelopes and theme-file pointers) via the pure `resolveStyle`
 * resolver in `@wordpress/global-styles-engine`. All store access lives here;
 * the panels stay presentational.
 *
 * Before the `globalStylesDataKey` payload settles (hydration) or when
 * `blockName` is missing, the hook returns empty value and source objects, so
 * each panel reads no inherited value and renders its local value alone.
 *
 * @param blockName     Selected block name (e.g. `core/heading`).
 * @param className     Block `className` used to detect an applied variation.
 * @param selectedState Selected block style state (`{ viewport, pseudo }`), or null for the default state.
 * @return Merged panel-scoped payload and source map.
 */
export function useResolvedStyle(
	blockName: string | null | undefined,
	className?: string | null,
	selectedState: BlockStyleState | null = null
) {
	const { variationName, headingLevel } = useVariationAndElements(
		blockName,
		className
	);
	const globalStyles = useRawGlobalStyles();

	return useMemo( () => {
		if ( ! blockName ) {
			return { value: {}, sources: {} };
		}
		return resolveStyle( globalStyles, {
			blockName,
			variationName,
			elements: getElementLayers( blockName, headingLevel ),
			viewport: selectedState?.viewport ?? null,
			pseudoState: selectedState?.pseudo ?? null,
		} );
	}, [
		blockName,
		variationName,
		headingLevel,
		globalStyles,
		selectedState,
	] );
}
